exercise.solution:
function isGoodCommitMessage(message) {
  if (typeof message !== 'string') return false;

  const lines = message.split('\n');
  const subject = lines[0];

  if (subject.length === 0 || subject.length > 50) return false;
  if (subject.endsWith('.')) return false;
  if (!/^[A-Z]/.test(subject)) return false;

  if (lines.length > 1 && lines[1] !== '') return false;

  return true;
}

function summarize(files) {
  const result = {};

  for (const file of files) {
    result[file.status] = (result[file.status] ?? 0) + 1;
  }

  return result;
}

